		}
		return err
	}
	if _, err := w.Write(b); err != nil {
		if IsClientAbort(err) {
			return ErrClientAbort
		}
		return err
	}
	if _, err := w.Write([]byte("\n\n")); err != nil {
		if IsClientAbort(err) {
			return ErrClientAbort
		}
		return err
	}
