func main() {
	// Test with curly quotes
	tests := []string{
		`"hello"`,   // ASCII double quote
		`"hello"`,   // U+201C LEFT DOUBLE QUOTATION MARK
		`"hello"`,   // U+201D RIGHT DOUBLE QUOTATION MARK
		`'hello'`,   // ASCII single quote
		`'hello'`,   // U+2018 LEFT SINGLE QUOTATION MARK
		`'hello'`,   // U+2019 RIGHT SINGLE QUOTATION MARK
		`—hello—`,   // U+2014 EM DASH
		`hello`,     // ASCII en dash
	}

	for _, tok := range tests {
		orig := tok
		tok = strings.ToLower(tok)
		tok = strings.TrimSpace(tok)
		tok = strings.Trim(tok, ".,;:!?()[]{}\"'")
		same := orig == tok
		fmt.Printf("Orig: %q -> After: %q (same: %v)\n", orig, tok, same)
	}

	// Check what unicode categories these are
	fmt.Printf("\nU+201C category: %v\n", unicode.IsLetter(rune(0x201C)))
	fmt.Printf("U+201D category: %v\n", unicode.IsLetter(rune(0x201D)))
}
